import sys

def min_path_best(grid, m, n):
    dp = [0] * n
    for i in range(m):
        for j in range(n):
            if i == 0 and j == 0:
                dp[0] = grid[0][0]
            elif i == 0:
                dp[j] = dp[j - 1] + grid[0][j]
            elif j == 0:
                dp[0] += grid[i][0]
            else:
                dp[j] = min(dp[j], dp[j - 1]) + grid[i][j]
    return dp[n - 1]

if __name__ == '__main__':
    data = sys.stdin.read().split()
    if not data:
        sys.exit(0)
    m, n = int(data[0]), int(data[1])
    grid = []
    idx = 2
    for _ in range(m):
        grid.append([int(x) for x in data[idx:idx + n]])
        idx += n
    print(min_path_best(grid, m, n))
